///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_openChrgDetlCnfm
 * @description open Chrg Detl Cnfm 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_openChrgDetlCnfm = async function () {
    const sbmOptions = {
        id: "tx_fn_openChrgDetlCnfm",
        method: "post",
        action: "/strip/strip.do?method=searchStripChrgDetl",
        ref: "dma_openChrgDetlCnfmReq",
        target: "dlt_bndApctTpCdList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_save
 * @description save 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_save = async function (action) {
    const sbmOptions = {
        id: "tx_fn_save",
        method: "post",
        action: action ?? "/strip/strip.do?method=saveStripAddMerge",
        ref: "dma_saveReq",
        target: "dlt_bndApctTpCdList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
